}
function save(table, rows) {
  localStorage.setItem('bwanali_' + table, JSON.stringify(rows));
  window.dispatchEvent(new CustomEvent('db-change', { detail: { table } }));
}

if (!localStorage.getItem('bwanali_seeded')) {
  save('stores', [{ id: 'store-1', name: 'Demo Store', subscription_status: 'trialing', trial_started_at: new Date().toISOString(), subscription_plan: 'monthly', locked: false }]);
